// === Tab: Metaballs ===
// Settings:
const ballCount = 100;
const maxVelocity = 5;
/////////////////

let metaballsShader;
let balls = [];

setup = () => {
	pixelDensity(1);
  createCanvas(windowWidth, windowHeight, WEBGL);
  initBalls();
  metaballsShader = createShader(vertexShader, fragmentShader);
}

initBalls = () => {
	for (let i = 0; i < ballCount; i++)
		balls.push({
			x: random(width),
			y: random(height),
			dX: random(-maxVelocity,maxVelocity),
			dY: random(-maxVelocity,maxVelocity)
		});
}

draw = () => {
	update();
	render();
}

update = () => {
	updateBallPositions();

	let ballsUniformArray = [];
	for (const ball of balls) {
		ballsUniformArray.push(ball.x);
		ballsUniformArray.push(ball.y);
	}

	metaballsShader.setUniform("dim",[width,height]);
	metaballsShader.setUniform(`balls`, ballsUniformArray);
}

updateBallPositions = () => {
	for (const i in balls) {
		const ball = balls[i];

		ball.x += ball.dX;
		ball.y += ball.dY;

		if (ball.x < 0) {
			ball.x = abs(ball.x);
			ball.dX *= -1;
		} else if (ball.x > width) {
			ball.x = width - (ball.x - width);
			ball.dX *= -1;
		}
 		if (ball.y < 0) {
			ball.y = abs(ball.y);
			ball.dY *= -1;
		} else if (ball.y > height) {
			ball.y = height - (ball.y - height);
			ball.dY *= -1;
		}
	}
}

render = () => {
	shader(metaballsShader); //Set active shader to metaballsShader
  noStroke(); //Remove stroke around quad
  quad(-1, -1, 1, -1, 1, 1, -1, 1); //Draw quad filling screen with currently active shader (metaballsShader)
}


// === Tab: vertexShader ===
let vertexShader = `
attribute vec3 aPosition;
varying vec2 vPos;
void main() {
  vPos = vec2(aPosition.x,aPosition.y);
	gl_Position = vec4(aPosition,1.0);
}
`;


// === Tab: fragmentShader ===
//noprotect - Necessary to avoid OpenProcessing's use of LoopProtect to rewrite the loop of our shader.

let fragmentShader = `
precision highp float;
uniform vec2 dim;
uniform vec2 balls[${ballCount}];
varying vec2 vPos;

void main() {
	vec2 coord = ((vPos+1.0) / 2.0) * dim;

	float amplitude = 0.0;
	for (int i = 0; i < ${ballCount}; i++) {
		amplitude += exp(-1.0/3200.0 * (pow(coord.x - balls[i].x,2.0) + pow(coord.y - balls[i].y,2.0)));
	}
	amplitude = mod(2.0 * 255.0 * amplitude, 255.0) / 255.0;

  gl_FragColor = vec4(amplitude,amplitude,amplitude,1.0);
}
`;

